1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Incident = {
14	  cause: string;
15	  damages: Damage[];
16	};
17	
18	export type Step = {
19	  op: string;
20	  items?: Item[];
21	  policy?: number;
22	  incident?: Incident;
23	};
24	
25	export type Customer = {
26	  yearsWithMHPCO: number;
27	};
28	
29	export type Scenario = {
30	  customer: Customer;
31	  steps: Step[];
32	};
33	
34	export type QuoteResult = {
35	  premium: number;
36	};
37	
38	export type ClaimResult = {
39	  payout: number;
40	  remainingCap: number;
41	};
42	
43	// A scenario's results are heterogeneous: a quote step yields a premium, a
44	// claim step a payout and the cap left on its policy.
45	export type StepResult = QuoteResult | ClaimResult;
46	
47	export type ScenarioResults = {
48	  results: StepResult[];
49	};
50	
51	// --- Quotes ------------------------------------------------------------------
52	
53	const PROCESSING_FEE = 5;
54	
55	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
56	  sword: 100,
57	  amulet: 60,
58	  staff: 80,
59	  potion: 40,
60	  rune: 25,
61	  moonstone: 25,
62	};
63	
64	// Charged on every quote, unconditionally — it is the cost of assessing the
65	// items, not a penalty for being a new customer. Named "first insurance" in
66	// some of the domain material, which misleads: it does not depend on customer
67	// history or on the quote's position in the scenario.
68	const INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;
69	
70	const WHOLE_PERCENT = 100;
71	
72	const percentOf = (amount: number, percent: number): number =>
73	  (amount * percent) / WHOLE_PERCENT;
74	
75	// The price tables cover exactly the item types the MHPCO insures. Anything
76	// else is not a mispriced item, it is not an item at all, so a lookup miss is
77	// an error rather than a zero.
78	const priceOf = (
79	  table: Record<string, number>,
80	  item: Item,
81	  what: string,
82	): number => {
83	  const price = table[item.type];
84	
85	  if (price === undefined) {
86	    throw new Error(`unknown item type "${item.type}": no ${what}`);
87	  }
88	
89	  return price;
90	};
91	
92	const itemBasePremium = (item: Item): number =>
93	  priceOf(BASE_PREMIUM_BY_TYPE, item, "base premium");
94	
95	const BLOCK_SIZE = 3;
96	
97	const BLOCK_PREMIUM = 60;
98	
99	const sumOf = (amounts: number[]): number =>
100	  amounts.reduce((sum, amount) => sum + amount, 0);
101	
102	const formsABlock = (items: Item[]): boolean => items.length === BLOCK_SIZE;
103	
104	const sumOfItemBasePremiums = (items: Item[]): number =>
105	  sumOf(items.map(itemBasePremium));
106	
107	// Items of the same type are "alike" and are priced together, so the policy
108	// base premium is computed group by group rather than item by item.
109	const alikeGroups = (items: Item[]): Item[][] => {
110	  const groupsByType = new Map<string, Item[]>();
111	
112	  for (const item of items) {
113	    groupsByType.set(item.type, [...(groupsByType.get(item.type) ?? []), item]);
114	  }
115	
116	  return [...groupsByType.values()];
117	};
118	
119	const alikeGroupBasePremium = (alikeItems: Item[]): number =>
120	  formsABlock(alikeItems)
121	    ? BLOCK_PREMIUM
122	    : sumOfItemBasePremiums(alikeItems);
123	
124	const policyBasePremium = (items: Item[]): number =>
125	  sumOf(alikeGroups(items).map(alikeGroupBasePremium));
126	
127	const roundPremiumInMHPCOsFavor = (amount: number): number =>
128	  Math.ceil(amount);
129	
130	// The inputs a single quote is computed from: `items` drives the base premium
131	// and item-scoped surcharges, `customer` and `precedingQuoteCount` drive the
132	// policy-wide modifiers. The count is of preceding QUOTE steps, not of steps in
133	// general — a claim step is not a contract and must not trigger the follow-up
134	// discount.
135	type QuoteRequest = {
136	  customer: Customer;
137	  items: Item[];
138	  precedingQuoteCount: number;
139	};
140	
141	const LOYALTY_YEARS = 2;
142	
143	const LOYALTY_DISCOUNT_PERCENT = 20;
144	
145	// Modifier percents are signed so surcharges and discounts can be summed
146	// uniformly; a discount enters the sum as its negation.
147	const asDiscount = (percent: number): number => -percent;
148	
149	const isLoyal = (customer: Customer): boolean =>
150	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
151	
152	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
153	
154	const isFollowUpContract = (request: QuoteRequest): boolean =>
155	  request.precedingQuoteCount > 0;
156	
157	const policyModifierPercents = (request: QuoteRequest): number[] => [
158	  INITIAL_ASSESSMENT_SURCHARGE_PERCENT,
159	  ...(isLoyal(request.customer) ? [asDiscount(LOYALTY_DISCOUNT_PERCENT)] : []),
160	  ...(isFollowUpContract(request)
161	    ? [asDiscount(FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT)]
162	    : []),
163	];
164	
165	// Policy-wide modifiers do NOT compound: each is an independent percentage of
166	// the policy base premium, and they are summed. Chaining them (base * 1.1 * 0.8)
167	// would give a different, wrong answer.
168	const applyPolicyModifiers = (
169	  basePremium: number,
170	  request: QuoteRequest,
171	): number =>
172	  basePremium +
173	  sumOf(
174	    policyModifierPercents(request).map((percent) =>
175	      percentOf(basePremium, percent),
176	    ),
177	  );
178	
179	const CURSE_SURCHARGE_PERCENT = 50;
180	
181	const HIGH_ENCHANTMENT_LEVEL = 5;
182	
183	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
184	
185	const isHighlyEnchanted = (item: Item): boolean =>
186	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
187	
188	const isCursed = (item: Item): boolean => item.cursed === true;
189	
190	type ItemSurchargeRule = {
191	  applies: (item: Item) => boolean;
192	  percent: number;
193	};
194	
195	const ITEM_SURCHARGE_RULES: ItemSurchargeRule[] = [
196	  { applies: isCursed, percent: CURSE_SURCHARGE_PERCENT },
197	  { applies: isHighlyEnchanted, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
198	];
199	
200	// Item-scoped surcharges are charged on the item's own base premium, so they
201	// must NOT go through applyPolicyModifiers.
202	const itemSurcharges = (item: Item): number =>
203	  sumOf(
204	    ITEM_SURCHARGE_RULES.filter((rule) => rule.applies(item)).map((rule) =>
205	      percentOf(itemBasePremium(item), rule.percent),
206	    ),
207	  );
208	
209	const policyItemSurcharges = (items: Item[]): number =>
210	  sumOf(items.map(itemSurcharges));
211	
212	const quotePremium = (request: QuoteRequest): number =>
213	  roundPremiumInMHPCOsFavor(
214	    applyPolicyModifiers(policyBasePremium(request.items), request) +
215	      policyItemSurcharges(request.items) +
216	      PROCESSING_FEE,
217	  );
218	
219	// --- Claims -----------------------------------------------------------------
220	// An item's insurance value is what it is worth if destroyed, and is unrelated
221	// to its premium: the premium is what the customer pays to be covered. The two
222	// tables below happen to agree on a 10x ratio today, but that is a property of
223	// the current price list and not a rule of the domain — repricing premiums must
224	// not silently revalue payouts, so they stay separate.
225	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
226	  sword: 1000,
227	  amulet: 600,
228	  staff: 800,
229	  potion: 400,
230	  rune: 250,
231	  moonstone: 250,
232	};
233	
234	const itemInsuranceValue = (item: Item): number =>
235	  priceOf(INSURANCE_VALUE_BY_TYPE, item, "insurance value");
236	
237	const insuranceSum = (items: Item[]): number =>
238	  sumOf(items.map(itemInsuranceValue));
239	
240	// A policy pays out at most twice what it insures.
241	const CAP_MULTIPLIER = 2;
242	
243	const policyCap = (items: Item[]): number =>
244	  CAP_MULTIPLIER * insuranceSum(items);
245	
246	const DEDUCTIBLE = 100;
247	
248	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
249	
250	const HALF_REIMBURSEMENT_PERCENT = 50;
251	
252	const isHalfReimbursed = (item: Item): boolean =>
253	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;
254	
255	const DRAGON_MATERIAL = "dragon";
256	
257	const isDragonMaterial = (item: Item): boolean =>
258	  item.material === DRAGON_MATERIAL;
259	
260	const damagedItem = (insuredItems: Item[], damage: Damage): Item | undefined =>
261	  insuredItems.find((item) => item.type === damage.itemType);
262	
263	const FULL_REIMBURSEMENT_PERCENT = 100;
264	
265	// A reimbursement clause pays a stated percentage of the damage. Clauses are
266	// listed in precedence order and the first applicable one wins.
267	type ReimbursementClause = {
268	  applies: (item: Item) => boolean;
269	  percent: number;
270	};
271	
272	const REIMBURSEMENT_CLAUSES: ReimbursementClause[] = [
273	  // Half reimbursement outranks the dragon clause: the spec's "50 % rule wins"
274	  // example is a dragon-material item enchanted to 8, and it pays out half.
275	  { applies: isHalfReimbursed, percent: HALF_REIMBURSEMENT_PERCENT },
276	  // "Damage to items made of dragon material is fully reimbursed." This clause
277	  // is currently indistinguishable from the fallback below — every example it
278	  // matches would reimburse in full anyway, so removing it would not change a
279	  // single result, and no test can tell it is here. It is stated regardless
280	  // because it is a rule the domain asserts about dragon material, not an
281	  // accident of what the other rules happen to leave over. Should a future rule
282	  // ever reduce reimbursement below 100 % for some other reason, dragon items
283	  // must keep their full payout, and this line is what will say so.
284	  { applies: isDragonMaterial, percent: FULL_REIMBURSEMENT_PERCENT },
285	];
286	
287	// No insured item means no clause applies. That an unmatched damage reimburses
288	// in full is not a rule of the domain, only the current default: the pending
289	// "item not part of the policy" test will reject such a claim outright.
290	const reimbursementPercent = (item: Item | undefined): number =>
291	  (item === undefined
292	    ? undefined
293	    : REIMBURSEMENT_CLAUSES.find((clause) => clause.applies(item))?.percent) ??
294	  FULL_REIMBURSEMENT_PERCENT;
295	
296	// What a damage entry reimburses before the deductible: a percentage of the
297	// damage amount, decided by the clauses covering the damaged item.
298	const reimbursableAmount = (insuredItems: Item[], damage: Damage): number =>
299	  percentOf(
300	    damage.amount,
301	    reimbursementPercent(damagedItem(insuredItems, damage)),
302	  );
303	
304	// The deductible applies once per damage event, i.e. per entry in `damages`,
305	// and always last — after the clause has decided the reimbursable amount.
306	const damagePayout = (insuredItems: Item[], damage: Damage): number =>
307	  reimbursableAmount(insuredItems, damage) - DEDUCTIBLE;
308	
309	// --- Running a scenario ------------------------------------------------------
310	
311	const isQuote = (step: Step): boolean => step.op === "quote";
312	
313	// What the scenario has accumulated so far. Steps are folded rather than mapped
314	// because a step's result depends on the steps before it: `precedingQuoteCount`
315	// drives the follow-up discount today, and claim steps will thread a remaining
316	// cap through the same carry.
317	// A policy as it stands at some point in the scenario: what it insures, and how
318	// much of its cap is left. The remaining cap belongs to the policy rather than
319	// to a side table because successive claims spend it down — it is the one part
320	// of a policy that changes over the scenario's lifetime.
321	type Policy = {
322	  insuredItems: Item[];
323	  remainingCap: number;
324	};
325	
326	const issuePolicy = (insuredItems: Item[]): Policy => ({
327	  insuredItems,
328	  remainingCap: policyCap(insuredItems),
329	});
330	
331	type ScenarioState = {
332	  results: StepResult[];
333	  precedingQuoteCount: number;
334	  // Policies issued by earlier quote steps, keyed by that step's index — a
335	  // claim names its policy that way (`step.policy`).
336	  policiesByStep: Map<number, Policy>;
337	};
338	
339	const INITIAL_STATE: ScenarioState = {
340	  results: [],
341	  precedingQuoteCount: 0,
342	  policiesByStep: new Map(),
343	};
344	
345	const withPolicy = (
346	  state: ScenarioState,
347	  stepIndex: number,
348	  policy: Policy,
349	): ScenarioState => ({
350	  ...state,
351	  policiesByStep: new Map(state.policiesByStep).set(stepIndex, policy),
352	});
353	
354	// Running a step is a state transition: it reads the carry accumulated by the
355	// preceding steps and returns the next carry. Every step kind gets its own
356	// runner, so `runStep` below is pure dispatch on `op` — the place a claim runner
357	// will be added without touching the quote path.
358	type StepRunner = (
359	  customer: Customer,
360	  state: ScenarioState,
361	  step: Step,
362	  stepIndex: number,
363	) => ScenarioState;
364	
365	const appendResult = (
366	  state: ScenarioState,
367	  result: StepResult,
368	): ScenarioState => ({ ...state, results: [...state.results, result] });
369	
370	const runQuoteStep: StepRunner = (customer, state, step, stepIndex) => {
371	  const items = step.items ?? [];
372	
373	  const premium = quotePremium({
374	    customer,
375	    items,
376	    precedingQuoteCount: state.precedingQuoteCount,
377	  });
378	
379	  return withPolicy(
380	    {
381	      ...appendResult(state, { premium }),
382	      precedingQuoteCount: state.precedingQuoteCount + 1,
383	    },
384	    stepIndex,
385	    issuePolicy(items),
386	  );
387	};
388	
389	// A claim names its policy by the index of the quote step that issued it. An
390	// unnamed or unknown policy currently resolves to nothing, and a claim against
391	// nothing insures nothing and pays nothing — the pending error-handling tests
392	// will replace that silent zero with a rejection.
393	// Resolving a claim's policy yields the key as well as the policy, so that
394	// debiting the cap later needs no second, separately-justified lookup of
395	// `step.policy` — the key travelled with the thing it addresses.
396	type ClaimedPolicy = { key: number; policy: Policy };
397	
398	const claimedPolicy = (
399	  state: ScenarioState,
400	  step: Step,
401	): ClaimedPolicy | undefined => {
402	  if (step.policy === undefined) return undefined;
403	
404	  const policy = state.policiesByStep.get(step.policy);
405	
406	  return policy === undefined ? undefined : { key: step.policy, policy };
407	};
408	
409	const NO_POLICY: Policy = { insuredItems: [], remainingCap: 0 };
410	
411	const runClaimStep: StepRunner = (_customer, state, step) => {
412	  const damages = step.incident?.damages ?? [];
413	  const claim = claimedPolicy(state, step);
414	  const { insuredItems, remainingCap } = claim?.policy ?? NO_POLICY;
415	
416	  // The clamp is outside the per-damage sum: the whole claim is limited by
417	  // what is left of the policy's cap, not each damage individually.
418	  const desiredPayout = sumOf(
419	    damages.map((damage) => damagePayout(insuredItems, damage)),
420	  );
421	  const payout = Math.min(desiredPayout, remainingCap);
422	  const capAfterClaim = remainingCap - payout;
423	  const claimed = appendResult(state, { payout, remainingCap: capAfterClaim });
424	
425	  // Only a policy that exists can be debited. A claim naming no policy has
426	  // nothing to write back, so it leaves the policy table untouched rather than
427	  // recording the spend under a made-up key.
428	  return claim === undefined
429	    ? claimed
430	    : withPolicy(claimed, claim.key, {
431	        ...claim.policy,
432	        remainingCap: capAfterClaim,
433	      });
434	};
435	
436	const runStep: StepRunner = (customer, state, step, stepIndex) =>
437	  isQuote(step)
438	    ? runQuoteStep(customer, state, step, stepIndex)
439	    : runClaimStep(customer, state, step, stepIndex);
440	
441	// The customer is scenario-wide, so it is closed over rather than threaded
442	// through the fold alongside the per-step state.
443	const stepRunnerFor =
444	  (customer: Customer) =>
445	  (state: ScenarioState, step: Step, stepIndex: number) =>
446	    runStep(customer, state, step, stepIndex);
447	
448	export const runScenario = (scenario: Scenario): ScenarioResults => ({
449	  results: scenario.steps.reduce(stepRunnerFor(scenario.customer), INITIAL_STATE)
450	    .results,
451	});
