// The price tables cover exactly the item types the MHPCO insures. Anything
// else is not a mispriced item, it is not an item at all, so a lookup miss is
// an error rather than a zero.
const priceOf = (
  table: Record<string, number>,
  item: Item,
  what: string,
): number => {
  const price = table[item.type];

  if (price === undefined) {
    throw new Error(`unknown item type "${item.type}": no ${what}`);
  }

  return price;
};

const itemBasePremium = (item: Item): number =>
  priceOf(BASE_PREMIUM_BY_TYPE, item, "base premium");

