// A claim names its policy by the index of the quote step that issued it. An
// unnamed or unknown policy currently resolves to nothing, and a claim against
// nothing insures nothing and pays nothing — the pending error-handling tests
// will replace that silent zero with a rejection.
// Resolving a claim's policy yields the key as well as the policy, so that
// debiting the cap later needs no second, separately-justified lookup of
// `step.policy` — the key travelled with the thing it addresses.
type ClaimedPolicy = { key: number; policy: Policy };

const claimedPolicy = (
  state: ScenarioState,
  step: Step,
): ClaimedPolicy | undefined => {
  if (step.policy === undefined) return undefined;

  const policy = state.policiesByStep.get(step.policy);

  return policy === undefined ? undefined : { key: step.policy, policy };
};

const NO_POLICY: Policy = { insuredItems: [], remainingCap: 0 };

const runClaimStep: StepRunner = (_customer, state, step) => {
  const damages = step.incident?.damages ?? [];
  const claim = claimedPolicy(state, step);
  const { insuredItems, remainingCap } = claim?.policy ?? NO_POLICY;

  // The clamp is outside the per-damage sum: the whole claim is limited by
  // what is left of the policy's cap, not each damage individually.
  const desiredPayout = sumOf(
    damages.map((damage) => damagePayout(insuredItems, damage)),
  );
  const payout = Math.min(desiredPayout, remainingCap);
  const capAfterClaim = remainingCap - payout;
  const claimed = appendResult(state, { payout, remainingCap: capAfterClaim });

  // Only a policy that exists can be debited. A claim naming no policy has
  // nothing to write back, so it leaves the policy table untouched rather than
  // recording the spend under a made-up key.
  return claim === undefined
    ? claimed
    : withPolicy(claimed, claim.key, {
        ...claim.policy,
        remainingCap: capAfterClaim,
      });
};

