  const policy =
    step.policy === undefined
      ? undefined
      : state.policiesByStep.get(step.policy);

  if (step.policy === undefined || policy === undefined) {
    throw new Error(`claim against unknown policy ${step.policy}`);
  }

  return { key: step.policy, policy };
};

